def clip_recall(highlights, clips):
    """Return the fraction of highlights found by the clips.

    Both arguments are lists of (start_s, end_s) tuples.
    A highlight is found when a clip overlaps it, and each clip can
    find at most one highlight. A single clip spanning several
    highlights therefore counts once. The function uses a maximum
    one-to-one matching between highlights and the clips that
    overlap them.

    Intervals that only touch at an endpoint do not count as
    overlapping. Returns 0.0 when there are no highlights.
    """
    if not highlights:
        return 0.0

    def _norm(interval):
        a, b = interval
        return (a, b) if a <= b else (b, a)

    norm_highlights = [_norm(h) for h in highlights]
    norm_clips = [_norm(c) for c in clips]

    # For each highlight, list the clips that overlap it.
    adjacency = []
    for h_start, h_end in norm_highlights:
        overlapping = [
            j
            for j, (c_start, c_end) in enumerate(norm_clips)
            if c_start < h_end and h_start < c_end
        ]
        adjacency.append(overlapping)

    # Maximum bipartite matching using augmenting paths (Kuhn's algorithm).
    clip_owner = [-1] * len(norm_clips)

    def _try_assign(h_idx, visited):
        for c_idx in adjacency[h_idx]:
            if visited[c_idx]:
                continue
            visited[c_idx] = True
            if clip_owner[c_idx] == -1 or _try_assign(clip_owner[c_idx], visited):
                clip_owner[c_idx] = h_idx
                return True
        return False

    found = 0
    for h_idx in range(len(norm_highlights)):
        if adjacency[h_idx] and _try_assign(h_idx, [False] * len(norm_clips)):
            found += 1

    return found / len(highlights)
